import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { /* primitives are imported for side‑effects only */ } from '@/primitives';
import { /* text utilities are imported for side‑effects only */ } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // ----- plane geometry & material -----
  const geometry = new PlaneGeometry(1.5, 0.94); // approximate 512×320 aspect
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously, keep reference for cleanup
  let texture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // fail silently – material will stay untextured
    });

  // ----- text label -----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text || item.content || '', {
      fontSize: item.typography?.fontSize ?? 42,
      color: config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ----- userData handlers & cleanup -----
  root.userData.handlers = {};

  const timelines = []; // store any GSAP timelines (none for this node)

  root.userData.cleanup = () => {
    // dispose material & geometry
    material.dispose();
    geometry.dispose();

    // dispose loaded texture
    if (texture) texture.dispose();

    // kill any GSAP timelines
    timelines.forEach((t) => t.kill());

    // clear handlers reference
    root.userData.handlers = {};
  };

  // expose promise for potential external waiting (optional)
  root.userData._texturePromise = texPromise;

  return root;
}
